    #[test]
    fn the_sbr_nioch_wave_is_one_dispatcher_row_and_holds_the_channel_family() {
        assert_eq!(
            RETIRED_SHADOW_SBR_NIOCH_TRIPLES,
            &[(
                "sun/nio/ch/SocketDispatcher",
                "close",
                "(Ljava/io/FileDescriptor;)V"
            )]
        );
        for (c, m, d) in RETIRED_SHADOW_SBR_NIOCH_TRIPLES {
            assert!(triple_is_retired_shadow(c, m, d));
        }
        for (c, m, d) in [
            // ACC_NATIVE on 17 / 21 / 25: nothing to yield to.
            (
                "sun/nio/ch/SocketDispatcher",
                "read0",
                "(Ljava/io/FileDescriptor;JI)I",
            ),
            (
                "sun/nio/ch/SocketDispatcher",
                "write0",
                "(Ljava/io/FileDescriptor;JI)I",
            ),
            // Declared on no image.
            ("sun/nio/ch/SocketDispatcher", "close0", "(I)V"),
            (
                "sun/nio/ch/SocketDispatcher",
                "invalidateAndClose",
                "(Ljava/io/FileDescriptor;)V",
            ),
            // ACC_NATIVE on 17; `signal0` unregistered.
            ("sun/nio/ch/NativeThread", "current", "()J"),
            ("sun/nio/ch/NativeThread", "signal", "(J)V"),
            // The object model's socket/channel/selector/datagram half was
            // retired by SBR wave 5 lane NIOREAL
            // (`the_sbr_nioreal_wave_retires_the_channel_family`); what this
            // wave held and wave 5 did not take is below.
            // The asynchronous half (`Simple/UnixAsynchronous*`, `FileLockImpl`)
            // was retired by SBR wave 6 lane ASYNCNET.
        ] {
            assert!(
                !triple_is_retired_shadow(c, m, d),
                "{c}.{m}{d} is HELD by SBR wave 2 lane NIOCH -- see its table's doc comment"
            );
        }
    }
    /// The `sequenced*` wave takes the three view accessors `keySet` /
