    /// Wave 8's deprecated-streams table: 13 rows over two classes, each
    /// class's WHOLE native surface (`<init>` through every accessor) taken
    /// together -- the carrier-defect precaution this table's own doc
    /// comment gives.
    #[test]
    fn wave_eight_deprecated_streams_is_whole_class_each() {
        assert_eq!(RETIRED_SHADOW_L4_DEPRECATED_STREAMS_TRIPLES.len(), 13);
        let mut lnis = 0;
        let mut sbis = 0;
        for (c, m, d) in RETIRED_SHADOW_L4_DEPRECATED_STREAMS_TRIPLES {
            assert!(
                *c == "java/io/LineNumberInputStream" || *c == "java/io/StringBufferInputStream",
                "{c}.{m}{d} is not one of this table's two classes"
            );
            if *c == "java/io/LineNumberInputStream" {
                lnis += 1;
            } else {
                sbis += 1;
            }
            assert!(
                triple_is_retired_shadow(c, m, d),
                "{c}.{m}{d} is in the wave-8 deprecated-streams table and the predicate cannot see it"
            );
        }
        assert_eq!(
            lnis, 8,
            "LineNumberInputStream's registered surface is 8 rows"
        );
        assert_eq!(
            sbis, 5,
            "StringBufferInputStream's registered surface is 5 rows"
        );

        // The constructor for each class is IN the table -- the whole point
        // of retiring the class together rather than per-accessor.
        assert!(triple_is_retired_shadow(
            "java/io/LineNumberInputStream",
            "<init>",
            "(Ljava/io/InputStream;)V"
        ));
        assert!(triple_is_retired_shadow(
            "java/io/StringBufferInputStream",
            "<init>",
            "(Ljava/lang/String;)V"
        ));
    }

