    /// Wave 10/13/14/15's 21 rows: `WindowsPath`'s `Path`-interface methods,
    /// landed after four real bugs found and fixed across four attempts.
    /// `getFileName`/`getParent` were excluded through wave 14 because both
    /// scan `this.path` directly for a literal `'\\'`, which this VM's
    /// `/`-stored `path` could never contain; wave 15 changed the STORAGE
    /// form to the JDK's own (`path_layout::stored_form`), which is what
    /// let them retire. `toRealPath` was blocked through wave 13
    /// (`WindowsNativeDispatcher.GetFullPathName0`, a Win32 native this
    /// VM had not implemented) and wave 14 implemented it, retiring both
    /// `toRealPath` overloads for the non-symlink case.
    #[test]
    fn wave_fifteen_windowspath_is_twentyone_rows() {
        assert_eq!(RETIRED_SHADOW_L4_WINDOWSPATH_TRIPLES.len(), 21);
        for (c, _, _) in RETIRED_SHADOW_L4_WINDOWSPATH_TRIPLES {
            assert_eq!(*c, "sun/nio/fs/WindowsPath");
        }
        for (m, d) in [
            ("compareTo", "(Ljava/nio/file/Path;)I"),
            ("endsWith", "(Ljava/nio/file/Path;)Z"),
            ("equals", "(Ljava/lang/Object;)Z"),
            ("getFileName", "()Ljava/nio/file/Path;"),
            ("getFileSystem", "()Ljava/nio/file/FileSystem;"),
            ("getName", "(I)Ljava/nio/file/Path;"),
            ("getNameCount", "()I"),
            ("getParent", "()Ljava/nio/file/Path;"),
            ("getParent", "()Lsun/nio/fs/WindowsPath;"),
            ("getRoot", "()Ljava/nio/file/Path;"),
            ("hashCode", "()I"),
            ("isAbsolute", "()Z"),
            ("normalize", "()Ljava/nio/file/Path;"),
            ("relativize", "(Ljava/nio/file/Path;)Ljava/nio/file/Path;"),
            ("resolve", "(Ljava/nio/file/Path;)Ljava/nio/file/Path;"),
            ("startsWith", "(Ljava/nio/file/Path;)Z"),
            ("subpath", "(II)Ljava/nio/file/Path;"),
            ("toAbsolutePath", "()Ljava/nio/file/Path;"),
            (
                "toRealPath",
                "([Ljava/nio/file/LinkOption;)Lsun/nio/fs/WindowsPath;",
            ),
            (
                "toRealPath",
                "([Ljava/nio/file/LinkOption;)Ljava/nio/file/Path;",
            ),
            ("toUri", "()Ljava/net/URI;"),
        ] {
            assert!(
                triple_is_retired_shadow("sun/nio/fs/WindowsPath", m, d),
                "sun/nio/fs/WindowsPath.{m}{d} is in the wave-15 WindowsPath table and the predicate cannot see it"
            );
        }
    }

    #[test]
    fn wave_seventeen_winntfs_is_eleven_rows() {
        assert_eq!(RETIRED_SHADOW_L4_WINNTFS_TRIPLES.len(), 11);
        for (c, m, d) in RETIRED_SHADOW_L4_WINNTFS_TRIPLES {
            assert_eq!(*c, "java/io/WinNTFileSystem");
            assert!(triple_is_retired_shadow(c, m, d), "{c}.{m}{d}");
            assert!(
                !m.ends_with('0'),
                "{m}: the *0 JNI natives are the surface the retired wrappers call and must stay"
            );
        }
        assert!(!triple_is_retired_shadow(
            "java/io/WinNTFileSystem",
            "list0",
            "(Ljava/io/File;)[Ljava/lang/String;"
        ));
        // Wave 17 asserted the Unix twin was NOT retired, because it was a
        // Windows-only measurement and said so. Wave 18 took that measurement
        // on a Linux host (`RETIRED_SHADOW_L4_UNIXFS_TRIPLES`), so the
        // assertion moves rather than being deleted: the row is retired, and
        // the `*0` native it calls still is not.
        assert!(triple_is_retired_shadow(
            "java/io/UnixFileSystem",
            "list",
            "(Ljava/io/File;)[Ljava/lang/String;"
        ));
        assert!(!triple_is_retired_shadow(
            "java/io/UnixFileSystem",
            "list0",
            "(Ljava/io/File;)[Ljava/lang/String;"
        ));
    }

    /// Wave 19: the ledger's remainder. Sorted, unique, every row retired, and
    /// the rows a named blocker covers stay OUT -- the `session`/`checkSession`
    /// pair the JOTP wave refuses most of all, since this table touches nine of
    /// the ten classes that carry it.
    #[test]
    fn wave_nineteen_is_the_ledger_remainder() {
        assert_eq!(RETIRED_SHADOW_L4_W19_TRIPLES.len(), 61);
        for (c, m, d) in RETIRED_SHADOW_L4_W19_TRIPLES {
            assert!(triple_is_retired_shadow(c, m, d), "{c}.{m}{d}");
            assert!(
                *m != "session" && *m != "checkSession",
                "{c}.{m}: the JOTP wave refuses the buffer session pair"
            );
        }
        for c in [
            "java/nio/ByteBuffer",
            "java/nio/DirectByteBuffer",
            "java/nio/HeapByteBuffer",
            "java/nio/MappedByteBuffer",
            "java/nio/DoubleBuffer",
            "java/nio/FloatBuffer",
            "java/nio/IntBuffer",
            "java/nio/LongBuffer",
            "java/nio/ShortBuffer",
        ] {
            // (SBR3 lane NIOBUF and JIT round 17 wave 2, lane nio2, retired the
            // whole session pair in their own tables; THIS table does not touch it.)
            for (m, d) in [
                ("session", "()Ljdk/internal/foreign/MemorySessionImpl;"),
                ("checkSession", "()V"),
            ] {
                assert!(!RETIRED_SHADOW_L4_W19_TRIPLES.contains(&(c, m, d)));
            }
        }
        // WITHDRAWN BY ITS OWN MEASUREMENT, and the withdrawal is the point of
        // the arm: `Files.readSymbolicLink` was in the first cut of this table
        // and `L4W5Sweep` came back with one new diff line --
        // `sym.readTarget = p-src.txt` on HotSpot against an EMPTY string here.
        // The retired body hands the JDK's own `UnixFileSystemProvider` the
        // `readlink0` bytes, and the `UnixPath` it builds from them is the
        // `byte[]`-backed carrier this VM does not populate
        // (`unixpath-carrier`). MEASURED 2026-09-20 with
        // `CRATONVM_UNRETIRE_NATIVE_SHADOW=java/nio/file/Files.readSymbolicLink`:
        // the line comes back.
        assert!(!triple_is_retired_shadow(
            "java/nio/file/Files",
            "readSymbolicLink",
            "(Ljava/nio/file/Path;)Ljava/nio/file/Path;"
        ));

        // The VM's own direct-memory hooks on the `JavaNioAccess` carrier (the `Bits$1`
        // counters were kept out here until SBR3 lane NIOBUF retired them with the real
        // `Bits` bytecode: `RETIRED_SHADOW_SBR3_NIOBUF_TRIPLES`).
        // (SBR5 lane FFMLINK retired `Buffer$2.reserveMemory` / `unreserveMemory` onto
        // the real `Bits` counters: `RETIRED_SHADOW_SBR5_FFMLINK_TRIPLES`.)
        for (c, m, d) in RETIRED_SHADOW_SBR5_FFMLINK_TRIPLES {
            assert!(triple_is_retired_shadow(c, m, d), "{c}.{m}{d}");
        }
    }

    /// Wave 18: the `java.io.UnixFileSystem` wrappers, the Linux twin of the
    /// test above. Same three invariants: eleven rows, all on that class, and
    /// no `*0` JNI native among them.
    #[test]
    fn wave_eighteen_unixfs_is_eleven_rows() {
        assert_eq!(RETIRED_SHADOW_L4_UNIXFS_TRIPLES.len(), 11);
        for (c, m, d) in RETIRED_SHADOW_L4_UNIXFS_TRIPLES {
            assert_eq!(*c, "java/io/UnixFileSystem");
            assert!(triple_is_retired_shadow(c, m, d), "{c}.{m}{d}");
            assert!(
                !m.ends_with('0'),
                "{m}: the *0 JNI natives are the surface the retired wrappers call and must stay"
            );
        }
        // The constructor writes the VM-minted carrier's fields; wave 17 kept
        // the Windows one native for the same reason.
        assert!(!triple_is_retired_shadow(
            "java/io/UnixFileSystem",
            "<init>",
            "()V"
        ));
    }

    #[test]
    fn wave_seventeen_files_and_provider_rows() {
        let n = |c: &str| {
            RETIRED_SHADOW_L4_FILES2_TRIPLES
                .iter()
                .filter(|(cc, _, _)| *cc == c)
                .count()
        };
        // 57 -> 55 (2026-09-22): `newFileSystem(URI, Map)` and
        // `readAttributes(Path,String,LinkOption[])` held out — see the
        // table's own doc comments on those rows.
        assert_eq!(RETIRED_SHADOW_L4_FILES2_TRIPLES.len(), 55);
        assert_eq!(n("java/nio/file/Files"), 32);
        assert_eq!(n("java/nio/file/FileVisitResult"), 2);
        assert_eq!(n("java/nio/file/spi/FileSystemProvider"), 2);
        assert_eq!(n("sun/nio/fs/WindowsFileStore"), 10);
        assert_eq!(n("sun/nio/fs/WindowsFileSystemProvider"), 7);
        // The four provider mutators travel with `Files`: alone, `Files`
        // recurses through their delegating natives (see the table's doc).
        for m in ["copy", "createDirectory", "delete", "move"] {
            assert!(
                RETIRED_SHADOW_L4_FILES2_TRIPLES
                    .iter()
                    .any(|(c, mm, _)| *c == "sun/nio/fs/WindowsFileSystemProvider" && *mm == m),
                "{m}: retiring `Files` without it is an infinite native recursion"
            );
        }
        // (`FileSystems.getDefault` was in this list; SBR round 2 wave 7 lane TAIL
        // retired it, see `RETIRED_SHADOW_SBR2_TAIL_TRIPLES`.)
        for (c, m, d) in [
            (
                "sun/nio/fs/WindowsFileSystemProvider",
                "getFileSystem",
                "(Ljava/net/URI;)Ljava/nio/file/FileSystem;",
            ),
            // `FileSystems.newFileSystem(Path, ClassLoader)` was held here
            // until the 2026-09-23 archive-provider wave
            // (`RETIRED_SHADOW_ARCHIVE_PROVIDER_TRIPLES`).
            (
                "sun/nio/fs/WindowsFileSystemProvider",
                "newFileSystem",
                "(Ljava/net/URI;Ljava/util/Map;)Ljava/nio/file/FileSystem;",
            ),
            (
                "sun/nio/fs/WindowsFileSystemProvider",
                "readAttributes",
                "(Ljava/nio/file/Path;Ljava/lang/String;[Ljava/nio/file/LinkOption;)Ljava/util/Map;",
            ),
        ] {
            assert!(
                !triple_is_retired_shadow(c, m, d),
                "{c}.{m}{d} has a named blocker (see the table's doc comment)"
            );
        }
    }

