    /// SBR round 2 wave 7 lane MH: four carrier-surface rows whose real bytecode
    /// was measured correct and gainful or free; the table is sorted, every row is
    /// reachable through the predicate, and the rows the lane TRIED and HELD
    /// (`RETIRED_SHADOW_SBR2_MH_HELD_TRIPLES`, unlisted) stay live `Bridge`s.
    #[test]
    fn the_sbr2_mh_wave_is_four_rows_and_the_held_table_is_unlisted() {
        let t = RETIRED_SHADOW_SBR2_MH_TRIPLES;
        for w in t.windows(2) {
            assert!(
                w[0] < w[1],
                "out of order or duplicated: {:?} then {:?}",
                w[0],
                w[1]
            );
        }
        for (c, m, d) in t {
            assert!(
                triple_is_retired_shadow(c, m, d),
                "unreachable entry: {c}.{m}{d}"
            );
        }
        let mut names: Vec<String> = t.iter().map(|(c, m, _)| format!("{c}.{m}")).collect();
        names.sort();
        assert_eq!(
            names,
            vec![
                "java/lang/invoke/MethodHandle.toString",
                "java/lang/invoke/MethodHandles.foldArguments",
                "java/lang/invoke/VarHandle.coordinateTypes",
                "java/lang/invoke/VarHandle.varType",
            ]
        );
        // The held table is sorted (so it can be spliced into the const unchanged),
        // disjoint from the landed one, and NOT consulted by the predicate.
        let h = RETIRED_SHADOW_SBR2_MH_HELD_TRIPLES;
        for w in h.windows(2) {
            assert!(
                w[0] < w[1],
                "held table out of order or duplicated: {:?} then {:?}",
                w[0],
                w[1]
            );
        }
        for (c, m, d) in h {
            assert!(
                t.binary_search(&(*c, *m, *d)).is_err(),
                "{c}.{m}{d} is both landed and held"
            );
            // SBR5 lane avh: `invokeWithArguments` and `bindTo` are reviewed `Intrinsic`s now
            // (a real handle's own door), so they are no longer in the family table.
            // Nor is `asType` since 3d31008561: the reviewed FFM-carrier
            // `Intrinsic` (`lang_invoke.rs`; real handles run their own body).
            if matches!(*m, "invokeWithArguments" | "bindTo" | "asType") {
                assert!(
                    !triple_is_retired_shadow(c, m, d),
                    "{c}.{m}{d} is an Intrinsic: a row would be inert"
                );
                continue;
            }
            assert!(
                triple_is_retired_shadow(c, m, d),
                "{c}.{m}{d} retired with the family (SBR3 mhperf)"
            );
        }
        // 60 until wave 8 lane SPRINGAPP retired `Lookup.findClass` (see the held table).
        assert_eq!(h.len(), 59);
    }

    /// SBR round 2 wave 9 lane MHFIX: the carrier fix landed, no row retires;
