    /// SBR wave 5, lane JSSE: the handshake half wave 4 held moves whole with
    /// its managers and keystore SPIs -- every row reachable, the classes and
    /// counts the table's doc names -- and what it keeps out stays out: the
    /// abstract rows (no `Code`), `engineGetAttributes` (not on JDK 17), and
    /// the native HTTPS client.
    #[test]
    fn the_sbr_jsse_wave_moves_the_handshake_half_whole() {
        let t = RETIRED_SHADOW_SBR_JSSE_TRIPLES;
        for w in t.windows(2) {
            assert!(
                w[0] < w[1],
                "out of order or duplicated: {:?} then {:?}",
                w[0],
                w[1]
            );
        }
        let mut per_class = std::collections::BTreeMap::<&str, usize>::new();
        for (c, m, d) in t {
            assert!(
                triple_is_retired_shadow(c, m, d),
                "unreachable entry: {c}.{m}{d}"
            );
            *per_class.entry(*c).or_default() += 1;
        }
        assert_eq!(
            per_class.into_iter().collect::<Vec<_>>(),
            vec![
                ("javax/net/ssl/KeyManagerFactory", 6),
                ("javax/net/ssl/SSLContext", 14),
                ("javax/net/ssl/SSLEngine", 2),
                ("javax/net/ssl/SSLParameters", 2),
                ("javax/net/ssl/SSLServerSocket", 18),
                ("javax/net/ssl/SSLServerSocketFactory", 2),
                ("javax/net/ssl/SSLSocket", 23),
                ("javax/net/ssl/SSLSocketFactory", 2),
                ("javax/net/ssl/TrustManagerFactory", 6),
                ("sun/security/pkcs12/PKCS12KeyStore", 19),
                ("sun/security/pkcs12/PKCS12KeyStore$DualFormatPKCS12", 19),
                ("sun/security/provider/JavaKeyStore", 19),
                ("sun/security/provider/JavaKeyStore$CaseExactJKS", 19),
                ("sun/security/provider/JavaKeyStore$DualFormatJKS", 19),
                ("sun/security/provider/JavaKeyStore$JKS", 19),
                ("sun/security/ssl/KeyManagerFactoryImpl$SunX509", 2),
                ("sun/security/ssl/SSLEngineImpl", 34),
                ("sun/security/ssl/SSLSocketImpl$AppInputStream", 5),
                ("sun/security/ssl/SSLSocketImpl$AppOutputStream", 4),
                ("sun/security/ssl/SunX509KeyManagerImpl", 6),
                ("sun/security/ssl/TrustManagerFactoryImpl$PKIXFactory", 3),
                ("sun/security/ssl/TrustManagerFactoryImpl$SimpleFactory", 2),
                ("sun/security/ssl/X509KeyManagerImpl", 6),
                ("sun/security/ssl/X509TrustManagerImpl", 7),
            ]
        );
        assert_eq!(t.len(), 258);
        // The key the native gates (`t27_tls::real_jsse_family`, the dispatch
        // doors) are keyed on is in the table.
        assert!(triple_is_retired_shadow(
            "javax/net/ssl/SSLContext",
            "getInstance",
            "(Ljava/lang/String;)Ljavax/net/ssl/SSLContext;"
        ));
        for (c, m, d) in [
            // Abstract: no `Code`; `--compatible`'s carriers are served by these.
            ("javax/net/ssl/SSLSocket", "startHandshake", "()V"),
            (
                "javax/net/ssl/SSLSocket",
                "getSession",
                "()Ljavax/net/ssl/SSLSession;",
            ),
            (
                "javax/net/ssl/SSLSocketFactory",
                "createSocket",
                "(Ljava/net/Socket;Ljava/lang/String;IZ)Ljava/net/Socket;",
            ),
            (
                "javax/net/ssl/SSLSocketFactory",
                "createSocket",
                "(Ljava/lang/String;I)Ljava/net/Socket;",
            ),
            (
                "javax/net/ssl/SSLServerSocketFactory",
                "createServerSocket",
                "(I)Ljava/net/ServerSocket;",
            ),
            ("javax/net/ssl/SSLEngine", "beginHandshake", "()V"),
            // Declared on 21/25, not on 17.
            (
                "sun/security/pkcs12/PKCS12KeyStore",
                "engineGetAttributes",
                "(Ljava/lang/String;)Ljava/util/Set;",
            ),
            (
                "sun/security/provider/JavaKeyStore$JKS",
                "engineGetAttributes",
                "(Ljava/lang/String;)Ljava/util/Set;",
            ),
            // Declared on no image.
            (
                "sun/security/ssl/SSLEngineImpl",
                "setApplicationProtocols",
                "([Ljava/lang/String;)V",
            ),
        ] {
            assert!(
                !triple_is_retired_shadow(c, m, d),
                "{c}.{m}{d} is kept out on purpose (see the table's doc)"
            );
        }
    }

