    /// The rows with no `Code` to yield to stay registered: abstract targets, the
    /// constructors the `sun` connection class does not declare, and the VM's own
    /// dispatcher `Runnable`. (Wave 6 retired the server, the client and the HTTPS
    /// carrier: `the_sbr_httpstack_wave_retires_the_http_stack_whole`.)
    #[test]
    fn the_sbr_http_wave_keeps_the_rows_without_code() {
        for (c, m, d) in [
            ("com/sun/net/httpserver/HttpExchange", "getRequestHeaders", "()Lcom/sun/net/httpserver/Headers;"),
            ("CratonVM$HttpServerLoop", "run", "()V"),
            ("java/net/http/HttpClient", "send", "(Ljava/net/http/HttpRequest;Ljava/net/http/HttpResponse$BodyHandler;)Ljava/net/http/HttpResponse;"),
            ("java/net/http/HttpRequest$Builder", "build", "()Ljava/net/http/HttpRequest;"),
            ("java/net/HttpURLConnection", "connect", "()V"),
            ("java/net/HttpURLConnection", "disconnect", "()V"),
            ("java/net/HttpURLConnection", "usingProxy", "()Z"),
            ("java/net/URLConnection", "connect", "()V"),
            ("sun/net/www/protocol/http/HttpURLConnection", "<init>", "(Ljava/net/URL;)V"),
            ("sun/net/www/protocol/http/HttpURLConnection", "<init>", "()V"),
            // Abstract on the JDK's own class.
            ("javax/net/ssl/HttpsURLConnection", "connect", "()V"),
            ("javax/net/ssl/HttpsURLConnection", "disconnect", "()V"),
            ("javax/net/ssl/HttpsURLConnection", "usingProxy", "()Z"),
            ("javax/net/ssl/HttpsURLConnection", "getCipherSuite", "()Ljava/lang/String;"),
            // Declared on no image.
            ("javax/net/ssl/HttpsURLConnection", "<init>", "()V"),
            ("sun/net/www/protocol/https/HttpsURLConnectionImpl", "<init>", "()V"),
            ("sun/net/spi/DefaultProxySelector", "init", "()V"),
        ] {
            assert!(!triple_is_retired_shadow(c, m, d), "{c}.{m}{d} has no bytecode to yield to");
        }
    }

