    fn the_sbr_system_wave_retires_the_bootstrap_plumbing() {
        for w in RETIRED_SHADOW_SBR_SYSTEM_TRIPLES.windows(2) {
            assert!(
                w[0] < w[1],
                "out of order or duplicated: {:?} then {:?}",
                w[0],
                w[1]
            );
        }
        let mut classes = std::collections::BTreeSet::new();
        for (c, m, d) in RETIRED_SHADOW_SBR_SYSTEM_TRIPLES {
            assert!(
                triple_is_retired_shadow(c, m, d),
                "{c}.{m}{d} is in the SBR SYSTEM table and the predicate cannot see it"
            );
            classes.insert(*c);
        }
        assert_eq!(
            classes.into_iter().collect::<Vec<_>>(),
            vec![
                "java/lang/System",
                "java/lang/System$1",
                "jdk/internal/access/SharedSecrets",
                "jdk/internal/loader/BootLoader",
                "jdk/internal/logger/DefaultLoggerFinder",
                "jdk/internal/misc/VM",
            ]
        );
        for (c, m, d) in [
            // (`getProperties`/`setProperty`/`clearProperty` and the exit path were held
            // here until SBR5 lane SYSPROPS.) Still held:
            (
                "java/lang/System",
                "setProperties",
                "(Ljava/util/Properties;)V",
            ),
            // (`System$1.findBootstrapClassOrNull` was held on "`ClassLoader.
            // findBootstrapClass` has no native": it has one, registered in
            // `native-builtins/src/lib.rs` with loading semantics. SBR round 2
            // wave 7 lane TAIL retired the row in `RETIRED_SHADOW_SBR2_TAIL_TRIPLES`.)
            // Held: the real body waits on a lock the launcher never notifies.
            ("jdk/internal/misc/VM", "awaitInitLevel", "(I)V"),
            // Not declared on 25: the lowercase spellings are for older images.
            (
                "java/lang/System$1",
                "getBytesUtf8NoRepl",
                "(Ljava/lang/String;)[B",
            ),
            (
                "java/lang/System$1",
                "newStringUtf8NoRepl",
                "([BII)Ljava/lang/String;",
            ),
        ] {
            assert!(
                !triple_is_retired_shadow(c, m, d),
                "{c}.{m}{d} is held (see the table's doc)"
            );
        }
    }

