    /// Round 15 wave 1 (lane shadow): the three CA6-1 thin-wrapper families
    /// are exactly their rows, every row reachable, and the TARGET each body
    /// forwards to stays live -- a retired wrapper over a retired target would
    /// have nothing to reach. Negative rows are written `[class, name,
    /// descriptor]` (see `the_sql_datetime_family_is_eleven_rows_on_three_classes`).
    #[test]
    fn the_r15_thin_wrapper_families_retire_the_wrapper_and_keep_the_target() {
        let families: [(&[(&str, &str, &str)], usize, &[&str]); 3] = [
            (
                RETIRED_SHADOW_SYSTEM_STREAM_SETTER_TRIPLES,
                3,
                &["java/lang/System"],
            ),
            (
                RETIRED_SHADOW_NIO_COVARIANT_BRIDGE_TRIPLES,
                if cfg!(windows) { 0 } else { 5 },
                &[
                    "sun/nio/ch/ServerSocketChannelImpl",
                    "sun/nio/ch/SocketChannelImpl",
                ],
            ),
            (
                RETIRED_SHADOW_REFLECT_GENERICS_DELEGATE_TRIPLES,
                3,
                &[
                    "sun/reflect/generics/reflectiveObjects/ParameterizedTypeImpl",
                    "sun/reflect/generics/reflectiveObjects/TypeVariableImpl",
                ],
            ),
        ];
        for (table, rows, classes) in families {
            assert_eq!(table.len(), rows);
            for (c, m, d) in table {
                assert!(classes.contains(c), "{c} is outside its family");
                assert!(triple_is_retired_shadow(c, m, d), "{c}.{m}{d} unreachable");
            }
        }
        for [c, m, d] in [
            // The `ACC_NATIVE` targets of the stream setters.
            ["java/lang/System", "setErr0", "(Ljava/io/PrintStream;)V"],
            ["java/lang/System", "setIn0", "(Ljava/io/InputStream;)V"],
            ["java/lang/System", "setOut0", "(Ljava/io/PrintStream;)V"],
            // The covariant overloads the javac bridges call.
            [
                "sun/nio/ch/SocketChannelImpl",
                "bind",
                "(Ljava/net/SocketAddress;)Ljava/nio/channels/SocketChannel;",
            ],
            [
                "sun/nio/ch/SocketChannelImpl",
                "setOption",
                "(Ljava/net/SocketOption;Ljava/lang/Object;)Ljava/nio/channels/SocketChannel;",
            ],
            [
                "sun/nio/ch/ServerSocketChannelImpl",
                "bind",
                "(Ljava/net/SocketAddress;I)Ljava/nio/channels/ServerSocketChannel;",
            ],
            [
                "sun/nio/ch/ServerSocketChannelImpl",
                "setOption",
                "(Ljava/net/SocketOption;Ljava/lang/Object;)Ljava/nio/channels/ServerSocketChannel;",
            ],
            // The minted abstract carriers keep their rows (module doc of the
            // NIO table), and so does the double-registered datagram twin.
            [
                "java/nio/channels/SocketChannel",
                "bind",
                "(Ljava/net/SocketAddress;)Ljava/nio/channels/NetworkChannel;",
            ],
            [
                "java/nio/channels/ServerSocketChannel",
                "bind",
                "(Ljava/net/SocketAddress;)Ljava/nio/channels/ServerSocketChannel;",
            ],
            [
                "sun/nio/ch/DatagramChannelImpl",
                "setOption",
                "(Ljava/net/SocketOption;Ljava/lang/Object;)Ljava/nio/channels/NetworkChannel;",
            ],
            // The generic-type targets, and the forced annotation factory.
            [
                "sun/reflect/generics/reflectiveObjects/ParameterizedTypeImpl",
                "getRawType",
                "()Ljava/lang/Class;",
            ],
            [
                "sun/reflect/generics/reflectiveObjects/TypeVariableImpl",
                "getName",
                "()Ljava/lang/String;",
            ],
            [
                "sun/reflect/generics/reflectiveObjects/TypeVariableImpl",
                "getAnnotations",
                "()[Ljava/lang/annotation/Annotation;",
            ],
            [
                "sun/reflect/annotation/AnnotatedTypeFactory$AnnotatedTypeBaseImpl",
                "getAnnotations",
                "()[Ljava/lang/annotation/Annotation;",
            ],
        ] {
            // The r15 families must not retire these targets. A row another table
            // retires on its own measurement (SBR round 1's NIO and generics rows
            // retire the covariant overloads too, the bytecode of both then runs)
            // is that table's decision, not this family's.
            for table in [
                RETIRED_SHADOW_SYSTEM_STREAM_SETTER_TRIPLES,
                RETIRED_SHADOW_NIO_COVARIANT_BRIDGE_TRIPLES,
                RETIRED_SHADOW_REFLECT_GENERICS_DELEGATE_TRIPLES,
            ] {
                assert!(!table.contains(&(c, m, d)), "{c}.{m}{d} must stay live");
            }
        }
    }

    /// Round 16 wave 15 (lane shadow): the JCEKS / DKS keystore engine
    /// surfaces move whole (the twenty `register_engine_surface` triples on
    /// each class, `engineGetAttributes` included), `javax.crypto.KEM` moves
    /// whole (the 17 rows `jca::kem::register` binds), every row is reachable,
    /// and the neighbours keep their own decisions: JSSE's held
    /// `engineGetAttributes` rows and the abstract `KEMSpi` stay out.
    #[test]
    fn the_r16_keystore_spi_and_kem_families_move_whole() {
        for (table, rows, classes) in [
            (
                RETIRED_SHADOW_R16_KEYSTORE_SPI_TRIPLES,
                40,
                &[
                    ("com/sun/crypto/provider/JceKeyStore", 20),
                    ("sun/security/provider/DomainKeyStore$DKS", 20),
                ][..],
            ),
            (
                RETIRED_SHADOW_R16_KEM_TRIPLES,
                17,
                &[
                    ("javax/crypto/KEM", 9),
                    ("javax/crypto/KEM$Decapsulator", 4),
                    ("javax/crypto/KEM$Encapsulator", 4),
                ][..],
            ),
        ] {
            for w in table.windows(2) {
                assert!(
                    w[0] < w[1],
                    "out of order or duplicated: {:?} then {:?}",
                    w[0],
                    w[1]
                );
            }
            let mut per_class = std::collections::BTreeMap::<&str, usize>::new();
            for (c, m, d) in table {
                assert!(
                    triple_is_retired_shadow(c, m, d),
                    "unreachable entry: {c}.{m}{d}"
                );
                *per_class.entry(*c).or_default() += 1;
            }
            assert_eq!(per_class.into_iter().collect::<Vec<_>>(), classes.to_vec());
            assert_eq!(table.len(), rows);
        }
        // Both keystore classes carry the same twenty methods.
        let methods = |class: &str| {
            RETIRED_SHADOW_R16_KEYSTORE_SPI_TRIPLES
                .iter()
                .filter(|(c, _, _)| *c == class)
                .map(|(_, m, d)| (*m, *d))
                .collect::<Vec<_>>()
        };
        assert_eq!(
            methods("com/sun/crypto/provider/JceKeyStore"),
            methods("sun/security/provider/DomainKeyStore$DKS")
        );
        for (c, m, d) in [
            // JSSE's own hold, unchanged by this wave.
            ("sun/security/pkcs12/PKCS12KeyStore", "engineGetAttributes", "(Ljava/lang/String;)Ljava/util/Set;"),
            // The abstract SPI and the outer DKS class: no rows registered, none retired.
            ("javax/crypto/KEMSpi", "engineNewEncapsulator", "(Ljava/security/PublicKey;Ljava/security/spec/AlgorithmParameterSpec;Ljava/security/SecureRandom;)Ljavax/crypto/KEMSpi$EncapsulatorSpi;"),
            ("sun/security/provider/DomainKeyStore", "engineSize", "()I"),
        ] {
            assert!(!triple_is_retired_shadow(c, m, d), "{c}.{m}{d} is not this wave's row");
        }
    }

    /// Interpreter round i2 wave 69, lane L1: `--compatible` adopts the seven
    /// retired `LockSupport` rows through `JdkLockSupport`, and nothing else on
    /// the locks package (`Unsafe.park` is not a row of any family).
    #[test]
    fn the_lock_support_rows_are_adopted_by_jdk_lock_support() {
        use cratonvm_types::HotSpotAlignment as Row;
        const LS: &str = "java/util/concurrent/locks/LockSupport";
        for (m, d) in [
            ("getBlocker", "(Ljava/lang/Thread;)Ljava/lang/Object;"),
            ("park", "()V"),
            ("park", "(Ljava/lang/Object;)V"),
            ("parkNanos", "(J)V"),
            ("parkNanos", "(Ljava/lang/Object;J)V"),
            ("parkUntil", "(Ljava/lang/Object;J)V"),
            ("unpark", "(Ljava/lang/Thread;)V"),
        ] {
            assert!(triple_is_retired_shadow(LS, m, d), "{m}{d}");
            assert_eq!(
                compat_row_of_shadow(LS, m, d),
                Some(Row::JdkLockSupport),
                "{m}{d}"
            );
        }
        assert_eq!(compat_row_of_stub_class(LS), None);
        assert!(compat_family_of_class("java/util/concurrent/locks/ReentrantLock").is_none());
        assert!(
            compat_family_of_class("java/util/concurrent/locks/AbstractQueuedSynchronizer")
                .is_none()
        );
        assert_eq!(
            compat_row_of_shadow("jdk/internal/misc/Unsafe", "park", "(ZJ)V"),
            None
        );
    }

