    /// Interpreter round i3 wave 72, lane L1: `AbstractQueuedLongSynchronizer`'s
    /// three retired rows are the `JdkAqls` family, and `CopyOnWriteArrayList`'s
    /// sixteen are the `JdkCopyOnWrite` family; neither is a stub-class
    /// family, and neither reaches `AbstractQueuedSynchronizer` or
    /// `CopyOnWriteArraySet`.
    #[test]
    fn the_aqls_and_copy_on_write_families_take_their_retired_rows() {
        use cratonvm_types::HotSpotAlignment as Row;
        const AQLS: &str = "java/util/concurrent/locks/AbstractQueuedLongSynchronizer";
        for (m, d) in [
            ("getState", "()J"),
            ("setState", "(J)V"),
            ("compareAndSetState", "(JJ)Z"),
        ] {
            assert!(triple_is_retired_shadow(AQLS, m, d), "{m}{d}");
            assert_eq!(
                compat_row_of_shadow(AQLS, m, d),
                Some(Row::JdkAqls),
                "{m}{d}"
            );
        }
        assert_eq!(compat_row_of_stub_class(AQLS), None);
        assert_eq!(
            compat_row_of_shadow(
                "java/util/concurrent/locks/AbstractQueuedSynchronizer",
                "compareAndSetState",
                "(II)Z"
            ),
            None
        );
        const COWAL: &str = "java/util/concurrent/CopyOnWriteArrayList";
        let rows: Vec<_> = RETIRED_SHADOW_TABLES
            .iter()
            .flat_map(|t| t.iter())
            .filter(|(c, _, _)| *c == COWAL)
            .collect();
        assert_eq!(rows.len(), 16, "{rows:?}");
        for (c, m, d) in rows {
            assert_eq!(
                compat_row_of_shadow(c, m, d),
                Some(Row::JdkCopyOnWrite),
                "{m}{d}"
            );
        }
        assert_eq!(compat_row_of_stub_class(COWAL), None);
        assert_ne!(
            compat_family_of_class("java/util/concurrent/CopyOnWriteArraySet").map(|f| f.row),
            Some(Row::JdkCopyOnWrite)
        );
        // Wave 74 (lane L1): the set has a row of its own, not the list's.
        assert_eq!(
            compat_row_of_shadow("java/util/concurrent/CopyOnWriteArraySet", "isEmpty", "()Z"),
            Some(Row::JdkCopyOnWriteArraySet)
        );
    }

    /// Interpreter round i3 wave 74, lane L1: the `JdkCopyOnWriteArraySet`
    /// family takes every one of the 24 `SET_CLASSES` triples
    /// `native-collections` `register_hashset_natives` registers on the class
    /// (the three retired rows through `classes`, the other 21 through
    /// `bridges`), is not a stub-class family, and reaches neither the list
    /// class nor `HashSet` / `LinkedHashSet`.
    #[test]
    fn the_copy_on_write_set_family_takes_the_whole_set_surface() {
        use cratonvm_types::HotSpotAlignment as Row;
        const COWAS: &str = "java/util/concurrent/CopyOnWriteArraySet";
        // The `register_hashset_natives` `SET_CLASSES` loop, in its order.
        let surface: &[(&str, &str)] = &[
            ("<init>", "()V"),
            ("<init>", "(I)V"),
            ("<init>", "(IF)V"),
            ("<init>", "(Ljava/util/Collection;)V"),
            ("size", "()I"),
            ("isEmpty", "()Z"),
            ("add", "(Ljava/lang/Object;)Z"),
            ("remove", "(Ljava/lang/Object;)Z"),
            ("contains", "(Ljava/lang/Object;)Z"),
            ("clear", "()V"),
            ("iterator", "()Ljava/util/Iterator;"),
            ("toArray", "()[Ljava/lang/Object;"),
            ("toArray", "([Ljava/lang/Object;)[Ljava/lang/Object;"),
            (
                "toArray",
                "(Ljava/util/function/IntFunction;)[Ljava/lang/Object;",
            ),
            ("toString", "()Ljava/lang/String;"),
            ("hashCode", "()I"),
            ("equals", "(Ljava/lang/Object;)Z"),
            ("forEach", "(Ljava/util/function/Consumer;)V"),
            ("stream", "()Ljava/util/stream/Stream;"),
            ("spliterator", "()Ljava/util/Spliterator;"),
            ("addAll", "(Ljava/util/Collection;)Z"),
            ("removeAll", "(Ljava/util/Collection;)Z"),
            ("retainAll", "(Ljava/util/Collection;)Z"),
            ("containsAll", "(Ljava/util/Collection;)Z"),
        ];
        assert_eq!(surface.len(), 24);
        let mut retired = 0;
        for &(m, d) in surface {
            assert_eq!(
                compat_row_of_shadow(COWAS, m, d),
                Some(Row::JdkCopyOnWriteArraySet),
                "{m}{d}"
            );
            if triple_is_retired_shadow(COWAS, m, d) {
                retired += 1;
            }
        }
        assert_eq!(
            retired, 3,
            "the SPRINGAPP rows: <init>()V, isEmpty, iterator"
        );
        // `bridges` lists exactly the non-retired 21, no stray triple.
        let family = compat_family_of_class(COWAS).expect("a family names the set");
        assert_eq!(family.row, Row::JdkCopyOnWriteArraySet);
        assert_eq!(family.bridges.len(), 21);
        for &(c, m, d) in family.bridges {
            assert_eq!(c, COWAS);
            assert!(surface.contains(&(m, d)), "{m}{d} is not a SET_CLASSES row");
            assert!(
                !triple_is_retired_shadow(c, m, d),
                "{m}{d} is retired: `classes` takes it"
            );
        }
        assert_eq!(compat_row_of_stub_class(COWAS), None);
        // The list keeps its own row; the HashSet family keeps its rows.
        assert_eq!(
            compat_family_of_class("java/util/concurrent/CopyOnWriteArrayList").map(|f| f.row),
            Some(Row::JdkCopyOnWrite)
        );
        for c in ["java/util/HashSet", "java/util/LinkedHashSet"] {
            assert_ne!(
                compat_row_of_shadow(c, "add", "(Ljava/lang/Object;)Z"),
                Some(Row::JdkCopyOnWriteArraySet),
                "{c}"
            );
        }
    }

