    /// nio20 (lane L4, NIO19-6): the reference, `Object`, `Optional` and
    /// `Unsafe` bulk rows are indexed to their own rows, nothing else of the
    /// same classes or tables is, and none of the four takes a companion stub.
    #[test]
    fn r20_reference_object_optional_and_unsafe_bulk_rows_are_their_families() {
        use cratonvm_types::HotSpotAlignment as Row;
        for (c, m, d, row) in [
            (
                "java/lang/ref/Reference",
                "reachabilityFence",
                "(Ljava/lang/Object;)V",
                Row::JdkReferences,
            ),
            (
                "java/lang/ref/WeakReference",
                "<init>",
                "(Ljava/lang/Object;)V",
                Row::JdkReferences,
            ),
            (
                "java/lang/ref/SoftReference",
                "get",
                "()Ljava/lang/Object;",
                Row::JdkReferences,
            ),
            (
                "java/lang/ref/ReferenceQueue",
                "remove",
                "(J)Ljava/lang/ref/Reference;",
                Row::JdkReferences,
            ),
            ("java/lang/Object", "<init>", "()V", Row::JdkObjectBodies),
            ("java/lang/Object", "wait", "(J)V", Row::JdkObjectBodies),
            (
                "java/util/Optional",
                "empty",
                "()Ljava/util/Optional;",
                Row::JdkOptional,
            ),
            ("java/util/OptionalInt", "getAsInt", "()I", Row::JdkOptional),
            (
                "jdk/internal/misc/Unsafe",
                "copyMemory",
                "(Ljava/lang/Object;JLjava/lang/Object;JJ)V",
                Row::JdkUnsafeBulkBodies,
            ),
            (
                "jdk/internal/misc/Unsafe",
                "setMemory",
                "(Ljava/lang/Object;JJB)V",
                Row::JdkUnsafeBulkBodies,
            ),
        ] {
            assert!(
                triple_is_retired_shadow(c, m, d),
                "witness no longer retired: {c}.{m}{d}"
            );
            assert_eq!(compat_row_of_shadow(c, m, d), Some(row), "{c}.{m}{d}");
        }
        // The rest of `Unsafe`'s retired rows are not adopted.
        for (c, m, d) in [
            ("jdk/internal/misc/Unsafe", "getInt", "(J)I"),
            ("jdk/internal/misc/Unsafe", "allocateMemory", "(J)J"),
            (
                "jdk/internal/misc/Unsafe",
                "objectFieldOffset",
                "(Ljava/lang/reflect/Field;)J",
            ),
        ] {
            assert!(
                triple_is_retired_shadow(c, m, d),
                "witness no longer retired: {c}.{m}{d}"
            );
            assert_eq!(compat_row_of_shadow(c, m, d), None, "{c}.{m}{d}");
        }
        // A non-retired row of a family class is not dropped by the class index.
        assert_eq!(
            compat_row_of_shadow("java/lang/ref/Reference", "enqueue", "()Z"),
            None
        );
        // Interpreter round i7 wave 135, lane L2: the three non-retired
        // `refersTo` spellings are the family's `bridges`, so they go with the
        // row (the `WeakReference` one is retired and goes by the class index).
        for c in [
            "java/lang/ref/Reference",
            "java/lang/ref/SoftReference",
            "java/lang/ref/PhantomReference",
            "java/lang/ref/WeakReference",
        ] {
            assert_eq!(
                compat_row_of_shadow(c, "refersTo", "(Ljava/lang/Object;)Z"),
                Some(Row::JdkReferences),
                "{c}.refersTo"
            );
        }
        assert_eq!(
            compat_row_of_shadow("java/lang/Object", "hashCode", "()I"),
            None
        );
        // `Object.equals` / `toString` are retired and carried the generic-
        // reflection carriers' answers: their own row (nio20 wave 2, L5), which
        // the registry holds unless the carriers are retired too.
        for (m, d) in [
            ("equals", "(Ljava/lang/Object;)Z"),
            ("toString", "()Ljava/lang/String;"),
        ] {
            assert!(
                triple_is_retired_shadow("java/lang/Object", m, d),
                "witness: Object.{m}"
            );
            assert_eq!(
                compat_row_of_shadow("java/lang/Object", m, d),
                Some(Row::JdkObjectIdentityBodies),
                "Object.{m}"
            );
        }
        assert!(compat_family_of_class("java/lang/Object").is_none());
        assert!(compat_family_of_class("java/lang/ref/Cleaner").is_none());
        // Interpreter round i6 wave 122 (lane L1): `String` is the
        // `JdkStringGetBytes` family's class (its two `getBytes` bridges).
        assert_eq!(
            compat_family_of_class("java/lang/String").map(|f| f.row),
            Some(Row::JdkStringGetBytes)
        );
        for c in [
            "java/lang/ref/WeakReference",
            "java/lang/Object",
            "java/util/OptionalLong",
            "jdk/internal/misc/Unsafe",
            "java/nio/channels/SocketChannel",
        ] {
            assert_eq!(
                compat_row_of_stub_class(c),
                None,
                "{c} takes no companion stub"
            );
        }
    }

    /// nio20 wave 2 (L5): the `ArrayList`, `Locale` and `Date` families take
    /// every retired row of their classes, `ArrayList$Itr` stays out (the VM
    /// mints it for `Vector` backings), and the stand-ins whose classes merely
    /// share a prefix are not taken.
    #[test]
    fn r20w2_array_list_locale_and_date_rows_are_their_families() {
        use cratonvm_types::HotSpotAlignment as Row;
        for (c, m, d, row) in [
            ("java/util/ArrayList", "size", "()I", Row::JdkArrayList),
            ("java/util/ArrayList", "<init>", "()V", Row::JdkArrayList),
            (
                "java/util/ArrayList$SubList",
                "get",
                "(I)Ljava/lang/Object;",
                Row::JdkArrayList,
            ),
            (
                "java/util/ArrayList$SubList",
                "size",
                "()I",
                Row::JdkArrayList,
            ),
            (
                "java/util/ArrayList$SubList$1",
                "hasNext",
                "()Z",
                Row::JdkArrayList,
            ),
            (
                "java/util/ArrayList$ListItr",
                "hasPrevious",
                "()Z",
                Row::JdkArrayList,
            ),
            (
                "java/util/Locale",
                "getDefault",
                "()Ljava/util/Locale;",
                Row::JdkLocale,
            ),
            (
                "java/util/Locale",
                "getLanguage",
                "()Ljava/lang/String;",
                Row::JdkLocale,
            ),
            (
                "java/util/Locale",
                "toLanguageTag",
                "()Ljava/lang/String;",
                Row::JdkLocale,
            ),
            ("java/util/Date", "getYear", "()I", Row::JdkDate),
            ("java/util/Date", "setMonth", "(I)V", Row::JdkDate),
            ("java/util/Date", "<init>", "(III)V", Row::JdkDate),
        ] {
            assert!(
                triple_is_retired_shadow(c, m, d),
                "witness no longer retired: {c}.{m}{d}"
            );
            assert_eq!(compat_row_of_shadow(c, m, d), Some(row), "{c}.{m}{d}");
        }
        // Every retired row of the three classes' families, whichever table.
        for (c, m, d) in RETIRED_SHADOW_L1_DATE_TRIPLES {
            assert_eq!(
                compat_row_of_shadow(c, m, d),
                Some(Row::JdkDate),
                "{c}.{m}{d}"
            );
        }
        // `ArrayList$Itr` is excepted: its retired `remove` stays registered.
        assert!(triple_is_retired_shadow(
            "java/util/ArrayList$Itr",
            "remove",
            "()V"
        ));
        assert_eq!(
            compat_row_of_shadow("java/util/ArrayList$Itr", "remove", "()V"),
            None
        );
        assert!(compat_family_of_class("java/util/ArrayList$Itr").is_none());
        assert_eq!(compat_row_of_stub_class("java/util/ArrayList$Itr"), None);
        // `ArrayList.subList` is a `SyntheticStub`, dropped as a companion.
        assert_eq!(
            compat_row_of_stub_class("java/util/ArrayList"),
            Some(Row::JdkArrayList)
        );
        assert_eq!(
            compat_row_of_stub_class("java/util/Locale$Builder"),
            Some(Row::JdkLocale)
        );
        // Not the families: neighbouring classes. (The provider adapters were
        // here too; nio20 wave 5 L4 gave them their own row,
        // `r20w5_locale_providers_family_takes_the_provider_floor`.)
        for c in [
            "java/util/Arrays$ArrayList",
            "java/util/TimeZone",
            "java/text/DateFormat",
        ] {
            assert!(
                compat_family_of_class(c).is_none(),
                "{c} is in no new family"
            );
        }
        // `CopyOnWriteArrayList` has its own row since interpreter round i3
        // wave 72 (lane L1), not `ArrayList`'s.
        assert_eq!(
            compat_family_of_class("java/util/concurrent/CopyOnWriteArrayList").map(|f| f.row),
            Some(Row::JdkCopyOnWrite)
        );
        assert_ne!(
            compat_family_of_class("sun/util/locale/provider/LocaleResources").map(|f| f.row),
            Some(Row::JdkLocale)
        );
        // `ArrayDeque` shares a table with `ArrayList` and a prefix with
        // neither family.
        assert_ne!(
            compat_row_of_shadow("java/util/ArrayDeque", "size", "()I"),
            Some(Row::JdkArrayList)
        );
        // `Object.equals` / `toString` are their own row (the registry holds
        // it until the reflect-type carriers are retired).
        assert!(is_object_identity_body_row(
            "java/lang/Object",
            "toString",
            "()Ljava/lang/String;"
        ));
        assert!(!is_object_identity_body_row(
            "java/lang/Object",
            "hashCode",
            "()I"
        ));
        assert!(!is_object_body_row(
            "java/lang/Object",
            "equals",
            "(Ljava/lang/Object;)Z"
        ));
        // `CompatFamily::bridges` (NIO20-L4-3): an entry is a family class's
        // triple that is NOT retired (a retired one the class index already
        // takes), and the index answers the family's row for it.
        for f in COMPAT_FAMILIES {
            for &(c, m, d) in f.bridges {
                assert!(
                    f.names_class(f.classes, c),
                    "{c} is not a {:?} class",
                    f.row
                );
                assert!(
                    !triple_is_retired_shadow(c, m, d),
                    "{c}.{m}{d} is retired: list it nowhere"
                );
                if family_exists_on_this_platform(f.row) {
                    assert_eq!(compat_row_of_shadow(c, m, d), Some(f.row), "{c}.{m}{d}");
                }
            }
        }
    }

    /// nio21 wave 1 (L4): `JdkConcurrentHashMap` takes every PHASE3 row (the
    /// map, its views and iterators, and `Properties`) and the two classes'
    /// stubs, and nothing of the `Unsafe`-served `tabAt` trio nor of the
    /// `ConcurrentMap` interface doors (kept since the nio21 dev merge); `JdkScalarAtomics` takes the four scalar atomics' retired
    /// rows and none of the `Array` / `FieldUpdater` classes'.
    #[test]
    fn r21w1_chm_pair_and_scalar_atomics_families() {
        use cratonvm_types::HotSpotAlignment as Row;
        for (c, m, d) in RETIRED_SHADOW_PHASE3_TRIPLES {
            assert_eq!(
                compat_row_of_shadow(c, m, d),
                Some(Row::JdkConcurrentHashMap),
                "{c}.{m}{d}"
            );
        }
        assert_eq!(
            compat_row_of_shadow(
                "java/util/concurrent/ConcurrentMap",
                "get",
                "(Ljava/lang/Object;)Ljava/lang/Object;"
            ),
            None
        );
        assert_eq!(
            compat_row_of_shadow(
                "java/util/concurrent/ConcurrentHashMap",
                "tabAt",
                "([Ljava/util/concurrent/ConcurrentHashMap$Node;I)Ljava/util/concurrent/ConcurrentHashMap$Node;"
            ),
            None
        );
        assert_eq!(
            compat_row_of_stub_class("java/util/concurrent/ConcurrentHashMap$TreeBin"),
            Some(Row::JdkConcurrentHashMap)
        );
        assert_eq!(
            compat_row_of_stub_class("java/util/Properties"),
            Some(Row::JdkConcurrentHashMap)
        );
        assert_eq!(
            compat_row_of_stub_class("java/util/concurrent/ConcurrentMap"),
            None
        );
        // The three `System` property rows go with the pair; `exit` does not.
        for (m, d) in [
            (
                "setProperty",
                "(Ljava/lang/String;Ljava/lang/String;)Ljava/lang/String;",
            ),
            ("clearProperty", "(Ljava/lang/String;)Ljava/lang/String;"),
            ("getProperties", "()Ljava/util/Properties;"),
        ] {
            assert_eq!(
                compat_row_of_shadow("java/lang/System", m, d),
                Some(Row::JdkConcurrentHashMap),
                "System.{m}"
            );
        }
        assert_ne!(
            compat_row_of_shadow("java/lang/System", "exit", "(I)V"),
            Some(Row::JdkConcurrentHashMap)
        );
        // Interpreter round i6 wave 119 (lane L5): `Hashtable`'s stubs are
        // the `JdkHashtable` row's.
        assert_eq!(compat_row_of_stub_class("java/util/Hashtable"), Some(Row::JdkHashtable));
        assert_eq!(
            compat_row_of_shadow(
                "java/util/concurrent/atomic/AtomicLong",
                "incrementAndGet",
                "()J"
            ),
            Some(Row::JdkScalarAtomics)
        );
        assert_eq!(
            compat_row_of_shadow(
                "java/util/concurrent/atomic/AtomicReference",
                "compareAndSet",
                "(Ljava/lang/Object;Ljava/lang/Object;)Z"
            ),
            Some(Row::JdkScalarAtomics)
        );
        assert_eq!(
            compat_row_of_shadow(
                "java/util/concurrent/atomic/AtomicIntegerArray",
                "get",
                "(I)I"
            ),
            Some(Row::JdkAtomicArrays)
        );
        assert_eq!(
            compat_row_of_shadow(
                "java/util/concurrent/atomic/AtomicLong",
                "VMSupportsCS8",
                "()Z"
            ),
            None
        );
        assert_eq!(
            compat_row_of_stub_class("java/util/concurrent/atomic/AtomicLong"),
            None
        );
    }

    /// nio21 wave 2 (L4): the five `HttpClient`-path class families take every
    /// retired row of their tables on their classes (and their nested
    /// classes), stub the same prefixes, and nothing next door; the
    /// carrier-thread-local row takes exactly its two tables' twelve rows and
    /// none of `System$1`'s other retired rows.
    #[test]
    fn r21w2_http_path_families_take_their_tables() {
        use cratonvm_types::HotSpotAlignment as Row;
        let by_class = |c: &str| -> Option<Row> {
            [
                ("java/util/TreeMap", Row::JdkTreeMap),
                ("java/util/TreeSet", Row::JdkTreeMap),
                ("java/util/LinkedList", Row::JdkLinkedCollections),
                ("java/util/ArrayDeque", Row::JdkLinkedCollections),
                (
                    "java/util/concurrent/CompletableFuture",
                    Row::JdkCompletableFuture,
                ),
                ("java/util/concurrent/TimeUnit", Row::JdkTimeUnit),
                ("java/util/concurrent/atomic/LongAdder", Row::JdkAdders),
                ("java/util/concurrent/atomic/DoubleAdder", Row::JdkAdders),
            ]
            .into_iter()
            .find(|(p, _)| c.starts_with(p))
            .map(|(_, r)| r)
        };
        let mut n = 0;
        for table in [
            RETIRED_SHADOW_L1_TM_TRIPLES,
            RETIRED_SHADOW_L1_TRIPLES,
            RETIRED_SHADOW_L5_TRIPLES,
            RETIRED_SHADOW_STATELESS_TRIPLES,
        ] {
            for &(c, m, d) in table {
                if let Some(row) = by_class(c) {
                    assert_eq!(compat_row_of_shadow(c, m, d), Some(row), "{c}.{m}{d}");
                    assert_eq!(compat_row_of_stub_class(c), Some(row), "{c}");
                    n += 1;
                }
            }
        }
        // 156 tree rows, 46 + 37 linked, 11 + 9 L5, 10 + 5 adders, at least.
        assert!(n >= 150 + 80 + 20 + 15, "{n} family rows");
        for (c, m, d) in [
            (
                "java/util/TreeMap",
                "put",
                "(Ljava/lang/Object;Ljava/lang/Object;)Ljava/lang/Object;",
            ),
            ("java/util/TreeSet", "isEmpty", "()Z"),
            ("java/util/TreeMap$EntryIterator", "hasNext", "()Z"),
            ("java/util/LinkedList$ListItr", "hasNext", "()Z"),
            ("java/util/ArrayDeque", "pollFirst", "()Ljava/lang/Object;"),
            (
                "java/util/concurrent/CompletableFuture",
                "complete",
                "(Ljava/lang/Object;)Z",
            ),
            (
                "java/util/concurrent/CompletableFuture",
                "completeValue",
                "(Ljava/lang/Object;)Z",
            ),
            ("java/util/concurrent/TimeUnit", "toNanos", "(J)J"),
            ("java/util/concurrent/atomic/LongAdder", "add", "(J)V"),
        ] {
            assert!(
                triple_is_retired_shadow(c, m, d),
                "census witness no longer retired: {c}.{m}{d}"
            );
            assert_eq!(compat_row_of_shadow(c, m, d), by_class(c), "{c}.{m}{d}");
        }
        // Next door, untouched.
        assert_eq!(
            compat_row_of_stub_class("java/util/concurrent/ConcurrentLinkedDeque"),
            None
        );
        assert_eq!(
            compat_row_of_stub_class("java/util/concurrent/atomic/LongAccumulator"),
            None
        );
        assert_eq!(
            compat_row_of_stub_class("java/util/concurrent/atomic/AtomicLong"),
            None
        );
        assert_eq!(compat_row_of_stub_class("java/util/PriorityQueue"), None);
        assert_ne!(
            compat_row_of_shadow(
                "java/util/concurrent/PriorityBlockingQueue",
                "poll",
                "(JLjava/util/concurrent/TimeUnit;)Ljava/lang/Object;"
            ),
            Some(Row::JdkTimeUnit)
        );
        // The carrier-thread-local row: both tables, nothing else.
        let mut tl = 0;
        for &(c, m, d) in RETIRED_SHADOW_JLA_CARRIER_TL_TRIPLES
            .iter()
            .chain(RETIRED_SHADOW_UTIL_TEMP_BUFFER_TRIPLES.iter())
        {
            assert!(is_carrier_thread_local_family_row(c, m, d), "{c}.{m}{d}");
            assert_eq!(
                compat_row_of_shadow(c, m, d),
                Some(Row::JdkCarrierThreadLocals),
                "{c}.{m}{d}"
            );
            tl += 1;
        }
        assert_eq!(tl, 8 + 4);
        assert!(!is_carrier_thread_local_family_row(
            "java/lang/System$1",
            "blockedOn",
            "(Lsun/nio/ch/Interruptible;)V"
        ));
        assert!(!is_carrier_thread_local_family_row(
            "jdk/internal/access/JavaLangAccess",
            "getCarrierThreadLocal",
            "(Ljdk/internal/misc/CarrierThreadLocal;)Ljava/lang/Object;"
        ));
        assert_eq!(compat_row_of_stub_class("sun/nio/ch/Util"), None);
        assert_eq!(compat_row_of_stub_class("java/lang/System$1"), None);
    }

    /// nio21 wave 3 (L1): the four new `HttpClient`-path rows. The interrupt
    /// row takes exactly `Thread`'s three interrupt-status rows; the `Unsafe`
    /// row takes its 31 reviewed delegations (every one retired) and none of
    /// the loops, off-heap accessors or kept bridges; the `URI` and
    /// `ByteArrayOutputStream` families take their tables whole and nothing
    /// next door.
    #[test]
    fn r21w3_interrupt_unsafe_uri_and_baos_rows() {
        use cratonvm_types::HotSpotAlignment as Row;
        for (m, d) in [
            ("interrupt", "()V"),
            ("isInterrupted", "()Z"),
            ("interrupted", "()Z"),
        ] {
            assert!(
                triple_is_retired_shadow("java/lang/Thread", m, d),
                "Thread.{m}"
            );
            assert_eq!(
                compat_row_of_shadow("java/lang/Thread", m, d),
                Some(Row::JdkThreadInterrupt),
                "Thread.{m}"
            );
        }
        let mut thread_rows = 0;
        for &(c, m, d) in RETIRED_SHADOW_SBR_THREAD_TRIPLES {
            if compat_row_of_shadow(c, m, d) == Some(Row::JdkThreadInterrupt) {
                thread_rows += 1;
            }
        }
        assert_eq!(thread_rows, 3, "only the interrupt-status rows");
        for (m, d) in [
            ("interrupt0", "()V"),
            ("clearInterruptEvent", "()V"),
            ("getName", "()Ljava/lang/String;"),
        ] {
            assert_ne!(
                compat_row_of_shadow("java/lang/Thread", m, d),
                Some(Row::JdkThreadInterrupt),
                "{m}"
            );
        }
        assert_eq!(compat_row_of_stub_class("java/lang/Thread"), None);

        assert_eq!(UNSAFE_DELEGATION_ROWS.len(), 31);
        for &(m, d) in UNSAFE_DELEGATION_ROWS {
            let c = "jdk/internal/misc/Unsafe";
            assert!(
                triple_is_retired_shadow(c, m, d),
                "Unsafe.{m}{d} is not retired"
            );
            assert_eq!(
                compat_row_of_shadow(c, m, d),
                Some(Row::JdkUnsafeDelegations),
                "Unsafe.{m}{d}"
            );
            // Not the delegations row's: the `sun/misc/Unsafe` spellings are the
            // `jdk-sun-misc-unsafe` family's (their bodies call
            // `beforeMemoryAccess()`), when they are retired at all.
            assert_ne!(
                compat_row_of_shadow("sun/misc/Unsafe", m, d),
                Some(Row::JdkUnsafeDelegations),
                "sun/misc/Unsafe.{m}{d}"
            );
        }
        for (m, d) in [
            ("getAndAddLong", "(Ljava/lang/Object;JJ)J"),
            (
                "getAndSetReference",
                "(Ljava/lang/Object;JLjava/lang/Object;)Ljava/lang/Object;",
            ),
            ("compareAndSetLong", "(Ljava/lang/Object;JJJ)Z"),
            ("getLongVolatile", "(Ljava/lang/Object;J)J"),
            ("fullFence", "()V"),
            ("getInt", "(J)I"),
        ] {
            assert_ne!(
                compat_row_of_shadow("jdk/internal/misc/Unsafe", m, d),
                Some(Row::JdkUnsafeDelegations),
                "Unsafe.{m}{d}"
            );
        }
        assert_eq!(compat_row_of_stub_class("jdk/internal/misc/Unsafe"), None);

        for &(c, m, d) in RETIRED_SHADOW_SBR_URI_TRIPLES {
            assert_eq!(
                compat_row_of_shadow(c, m, d),
                Some(Row::JdkUri),
                "{c}.{m}{d}"
            );
        }
        assert_eq!(compat_row_of_stub_class("java/net/URI"), Some(Row::JdkUri));
        assert_eq!(
            compat_row_of_stub_class("java/net/URISyntaxException"),
            None
        );
        assert_eq!(compat_row_of_stub_class("java/net/URL"), None);

        let mut baos = 0;
        for &(c, m, d) in RETIRED_SHADOW_L4_TRIPLES {
            if c == "java/io/ByteArrayOutputStream" {
                assert_eq!(
                    compat_row_of_shadow(c, m, d),
                    Some(Row::JdkByteArrayStreams),
                    "{c}.{m}{d}"
                );
                baos += 1;
            }
        }
        assert_eq!(baos, 13);
        assert_eq!(
            compat_row_of_stub_class("java/io/ByteArrayOutputStream"),
            Some(Row::JdkByteArrayStreams)
        );
        assert_eq!(compat_row_of_stub_class("java/io/OutputStream"), None);
        // Dev's `JdkProcess` family (i3) owns the process pipe stand-in; only BAOS must not.
        assert_ne!(
            compat_row_of_stub_class("cratonvm/synthetic/ProcessPipeOutputStream"),
            Some(Row::JdkByteArrayStreams)
        );
        assert_eq!(
            compat_row_of_stub_class("cratonvm/internal/HucBodyStream"),
            None
        );
        assert_ne!(
            compat_row_of_shadow("java/io/OutputStream", "write", "(I)V"),
            Some(Row::JdkByteArrayStreams)
        );
    }

    /// nio21 wave 4 (L1): `JdkSharedSecrets` takes exactly the
    /// `getJavaLangAccess` getter of `jdk/internal/access/SharedSecrets`
    /// (a retired row), no other getter, not the legacy package, and no
    /// `System$1` row.
    #[test]
    fn r21w4_shared_secrets_row_takes_the_jla_getter_only() {
        use cratonvm_types::HotSpotAlignment as Row;
        let ss = "jdk/internal/access/SharedSecrets";
        let jla = "()Ljdk/internal/access/JavaLangAccess;";
        assert!(triple_is_retired_shadow(ss, "getJavaLangAccess", jla));
        assert_eq!(
            compat_row_of_shadow(ss, "getJavaLangAccess", jla),
            Some(Row::JdkSharedSecrets)
        );
        let mut taken = 0;
        for &(c, m, d) in RETIRED_SHADOW_SBR_SYSTEM_TRIPLES
            .iter()
            .chain(RETIRED_SHADOW_JLA_CARRIER_TL_TRIPLES)
        {
            if compat_row_of_shadow(c, m, d) == Some(Row::JdkSharedSecrets) {
                assert_eq!((c, m, d), (ss, "getJavaLangAccess", jla));
                taken += 1;
            }
        }
        assert_eq!(taken, 1, "the getter is a row of the SBR System table");
        for (m, d) in [
            (
                "getJavaLangReflectAccess",
                "()Ljdk/internal/access/JavaLangReflectAccess;",
            ),
            ("getJavaNioAccess", "()Ljdk/internal/access/JavaNioAccess;"),
        ] {
            assert_ne!(
                compat_row_of_shadow(ss, m, d),
                Some(Row::JdkSharedSecrets),
                "{m}"
            );
        }
        assert_eq!(
            compat_row_of_shadow("jdk/internal/misc/SharedSecrets", "getJavaLangAccess", jla),
            None
        );
        assert_eq!(compat_row_of_stub_class(ss), None);
    }

    /// nio20 wave 5 (L4): `JdkLocaleProviders` takes every retired row of the
    /// provider floor and the two `java.text` families retired with it,
    /// whichever table retired it, plus the two `Currency` bridges; `TimeZone`,
    /// `Locale`, `DateFormat` and `Normalizer` are not its classes, and the
    /// abstract-method `ResourceBundle` bridges are not rows at all.
    #[test]
    fn r20w5_locale_providers_family_takes_the_provider_floor() {
        use cratonvm_types::HotSpotAlignment as Row;
        let floor = RETIRED_SHADOW_SBR_LOCALE2_TRIPLES
            .iter()
            .chain(RETIRED_SHADOW_L1_LP_TRIPLES)
            .chain(RETIRED_SHADOW_L1_BI_TRIPLES);
        let mut n = 0;
        for (c, m, d) in floor {
            assert_eq!(
                compat_row_of_shadow(c, m, d),
                Some(Row::JdkLocaleProviders),
                "{c}.{m}{d}"
            );
            n += 1;
        }
        assert!(n >= 22 + 2 + 17, "{n} provider-floor rows");
        for (c, m, d) in [
            (
                "java/util/ResourceBundle$Control",
                "getCandidateLocales",
                "(Ljava/lang/String;Ljava/util/Locale;)Ljava/util/List;",
            ),
            (
                "java/util/ResourceBundle$1",
                "setParent",
                "(Ljava/util/ResourceBundle;Ljava/util/ResourceBundle;)V",
            ),
            (
                "sun/util/locale/provider/CalendarDataUtility",
                "retrieveJavaTimeFieldValueNames",
                "(Ljava/lang/String;IILjava/util/Locale;)Ljava/util/Map;",
            ),
            (
                "java/text/DecimalFormatSymbols",
                "initialize",
                "(Ljava/util/Locale;)V",
            ),
            (
                "java/text/DecimalFormatSymbols",
                "getInstance",
                "(Ljava/util/Locale;)Ljava/text/DecimalFormatSymbols;",
            ),
        ] {
            assert!(
                triple_is_retired_shadow(c, m, d),
                "witness no longer retired: {c}.{m}{d}"
            );
            assert_eq!(
                compat_row_of_shadow(c, m, d),
                Some(Row::JdkLocaleProviders),
                "{c}.{m}{d}"
            );
        }
        // The two `Currency` display bridges go with the providers they ask.
        for m in ["getSymbol", "getDisplayName"] {
            assert_eq!(
                compat_row_of_shadow(
                    "java/util/Currency",
                    m,
                    "(Ljava/util/Locale;)Ljava/lang/String;"
                ),
                Some(Row::JdkLocaleProviders),
                "Currency.{m}"
            );
        }
        // The abstract-method bridges that serve a carrier stay registered.
        for (m, d) in [
            ("handleGetObject", "(Ljava/lang/String;)Ljava/lang/Object;"),
            ("getKeys", "()Ljava/util/Enumeration;"),
        ] {
            assert!(!triple_is_retired_shadow("java/util/ResourceBundle", m, d));
            assert_eq!(
                compat_row_of_shadow("java/util/ResourceBundle", m, d),
                None,
                "{m}{d}"
            );
        }
        // Neighbours that are other families or none.
        for (c, m, d) in RETIRED_SHADOW_SBR_LOCALE_TRIPLES {
            let row = compat_row_of_shadow(c, m, d);
            if *c == "java/util/TimeZone" && *m == "getDefaultRef" {
                // The one `TimeZone` row `Date.normalize` crosses: `JdkDate`'s.
                assert_eq!(row, Some(Row::JdkDate), "{c}.{m}{d}");
            } else if c.starts_with("java/util/TimeZone") {
                assert_eq!(row, None, "{c}.{m}{d}");
            } else if c.starts_with("java/util/Locale") {
                assert_eq!(row, Some(Row::JdkLocale), "{c}.{m}{d}");
            }
        }
        for c in [
            "java/util/TimeZone",
            "java/text/DateFormat",
            "java/text/Normalizer",
        ] {
            assert!(compat_family_of_class(c).is_none(), "{c}");
        }
        assert_eq!(
            compat_row_of_stub_class("sun/util/resources/LocaleData"),
            Some(Row::JdkLocaleProviders)
        );
        // `Currency` is a bridge-only member: no companion stub is dropped.
        assert_eq!(compat_row_of_stub_class("java/util/Currency"), None);
    }

    /// nio20 wave 6 (L5): `JdkPrintWriter` takes the seven retired
    /// `PrintWriter` rows and nothing of `PrintStream` or the other writers.
    #[test]
    fn r20w6_print_writer_family_is_print_writer_only() {
        use cratonvm_types::HotSpotAlignment as Row;
        for (c, m, d) in RETIRED_SHADOW_L4_PRINTWRITER_TRIPLES {
            assert_eq!(
                compat_row_of_shadow(c, m, d),
                Some(Row::JdkPrintWriter),
                "{c}.{m}{d}"
            );
        }
        assert_eq!(
            compat_row_of_stub_class("java/io/PrintWriter"),
            Some(Row::JdkPrintWriter)
        );
        for c in [
            "java/io/PrintStream",
            "java/io/StringWriter",
            "java/io/Writer",
            "java/io/OutputStreamWriter",
            "java/io/BufferedWriter",
        ] {
            assert!(compat_family_of_class(c).is_none(), "{c}");
            assert_eq!(compat_row_of_stub_class(c), None, "{c}");
        }
        // nio21 wave 3: `ByteArrayOutputStream` has a family of its own
        // (`jdk-byte-array-streams`), never the print-writer row.
        assert_ne!(
            compat_row_of_stub_class("java/io/ByteArrayOutputStream"),
            Some(Row::JdkPrintWriter)
        );
        assert!(Row::JdkPrintWriter.default_on());
        assert!(Row::JdkPrintWriter.needs_real_jdk());
    }

