/// JIT round 20 wave 17 (lane bridge): the `--jdk-only` yielded-bridge rows are
/// not registered by a strict real-JDK registry as `Bridge`s, and every other
/// shape (another mode, no real JDK, another kind) keeps them.
#[cfg(test)]
mod jr20_bridge_jdk_only_yielded_bridge_tests {
    use super::*;
    use crate::registry::{NativeContext, NativeKind, NativeMethodRegistry};
    use cratonvm_types::compat::CompatibilityMode;
    use cratonvm_types::error::MethodCallResult;
    use cratonvm_types::Value;

    fn cb(_ctx: &mut dyn NativeContext, _args: &[Value]) -> MethodCallResult {
        Ok(None)
    }

    fn registry(mode: CompatibilityMode, real_jdk: bool) -> NativeMethodRegistry {
        let mut r = NativeMethodRegistry::new();
        r.set_compatibility_mode(mode);
        r.set_real_jdk(real_jdk);
        r
    }

    #[test]
    fn the_tables_are_the_census_rows_and_none_is_a_retired_shadow() {
        assert_eq!(JDK_ONLY_YIELDED_BRIDGE_TRIPLES.len(), 7);
        #[cfg(unix)]
        assert_eq!(JDK_ONLY_YIELDED_MIRROR_TRIPLES.len(), 31);
        #[cfg(not(unix))]
        assert!(JDK_ONLY_YIELDED_MIRROR_TRIPLES.is_empty());
        for (c, m, d) in JDK_ONLY_YIELDED_BRIDGE_TRIPLES
            .iter()
            .chain(JDK_ONLY_YIELDED_MIRROR_TRIPLES.iter())
        {
            assert!(is_jdk_only_yielded_bridge(c, m, d), "{c}.{m}{d}");
            assert!(
                !triple_is_retired_shadow(c, m, d),
                "{c}.{m}{d} is a retired row, not this table's"
            );
        }
        // The reviewed Internal twins and the abstract interface rows stay.
        assert!(!is_jdk_only_yielded_bridge(
            "jdk/internal/misc/ScopedMemoryAccess",
            "getCharInternal",
            "(Ljdk/internal/foreign/MemorySessionImpl;Ljava/lang/Object;J)C",
        ));
        assert!(!is_jdk_only_yielded_bridge(
            "java/util/Spliterator",
            "tryAdvance",
            "(Ljava/util/function/Consumer;)Z",
        ));
    }

    #[test]
    fn only_a_strict_real_jdk_bridge_is_not_registered() {
        for &(c, m, d) in JDK_ONLY_YIELDED_BRIDGE_TRIPLES {
            let mut strict = registry(CompatibilityMode::JdkOnly, true);
            strict.register_with_kind(c, m, d, cb, NativeKind::Bridge);
            assert_eq!(strict.kind_of(c, m, d), None, "{c}.{m}{d}");

            let mut intrinsic = registry(CompatibilityMode::JdkOnly, true);
            intrinsic.register_with_kind(c, m, d, cb, NativeKind::Intrinsic);
            assert_eq!(
                intrinsic.kind_of(c, m, d),
                Some(NativeKind::Intrinsic),
                "{c}.{m}{d}"
            );

            let mut no_image = registry(CompatibilityMode::JdkOnly, false);
            no_image.register_with_kind(c, m, d, cb, NativeKind::Bridge);
            assert_eq!(
                no_image.kind_of(c, m, d),
                Some(NativeKind::Bridge),
                "{c}.{m}{d}"
            );

            let mut compatible = registry(CompatibilityMode::Compatible, false);
            compatible.register_with_kind(c, m, d, cb, NativeKind::Bridge);
            assert_eq!(
                compatible.kind_of(c, m, d),
                Some(NativeKind::Bridge),
                "{c}.{m}{d}"
            );
        }
    }

    /// Wave 19: `ClassLoader`'s three instance resource lookups are a reviewed
    /// `Intrinsic` under `--compatible` over a real JDK, from an ambient
    /// `Bridge` registration too, and stay a `Bridge` everywhere else.
    #[test]
    fn the_loader_resource_rows_are_compatible_intrinsics_only() {
        assert_eq!(COMPAT_LOADER_RESOURCE_INTRINSIC_TRIPLES.len(), 3);
        for &(c, m, d) in COMPAT_LOADER_RESOURCE_INTRINSIC_TRIPLES {
            assert!(is_compat_loader_resource_intrinsic(c, m, d), "{c}.{m}{d}");
            assert!(!triple_is_retired_shadow(c, m, d), "{c}.{m}{d}");
            assert!(!is_jdk_only_yielded_bridge(c, m, d), "{c}.{m}{d}");

            let mut compatible = registry(CompatibilityMode::Compatible, true);
            compatible.with_category(NativeKind::Bridge, |r| r.register(c, m, d, cb));
            assert_eq!(
                compatible.kind_of(c, m, d),
                Some(NativeKind::Intrinsic),
                "{c}.{m}{d}"
            );

            let mut strict = registry(CompatibilityMode::JdkOnly, true);
            strict.with_category(NativeKind::Bridge, |r| r.register(c, m, d, cb));
            assert_eq!(
                strict.kind_of(c, m, d),
                Some(NativeKind::Bridge),
                "{c}.{m}{d}"
            );

            let mut synthetic = registry(CompatibilityMode::Compatible, false);
            synthetic.with_category(NativeKind::Bridge, |r| r.register(c, m, d, cb));
            assert_eq!(
                synthetic.kind_of(c, m, d),
                Some(NativeKind::Bridge),
                "{c}.{m}{d}"
            );
        }
        // The static `getSystemResource*` forms share the callbacks and stay
        // `Bridge`s (every door already resolves them on `ClassLoader` itself).
        assert!(!is_compat_loader_resource_intrinsic(
            "java/lang/ClassLoader",
            "getSystemResource",
            "(Ljava/lang/String;)Ljava/net/URL;",
        ));
    }
}

/// JIT round j27 wave 5 (lane VMALIGN): the `JdkVmInitLevel` row takes exactly
/// `VM.initLevel()` and `VM.isBooted()` of the SBR System / L5 tables,
/// leaves the other retired `VM` rows native, and drops both registrations
/// under `--compatible` over a real JDK only.
#[cfg(test)]
mod j27_vmalign_jdk_vm_init_level_tests {
    use super::*;
    use crate::registry::{NativeContext, NativeKind, NativeMethodRegistry};
    use cratonvm_types::compat::CompatibilityMode;
    use cratonvm_types::error::MethodCallResult;
    use cratonvm_types::{HotSpotAlignment as Row, HotSpotAlignments, Value};

    const VM: &str = "jdk/internal/misc/VM";

    fn cb(_ctx: &mut dyn NativeContext, _args: &[Value]) -> MethodCallResult {
        Ok(None)
    }

    #[test]
    fn the_row_takes_init_level_and_is_booted_only() {
        // `isBooted` follows the opt-in `CRATONVM_COMPAT_FAST_BOOT_JDK_BOOTED`
        // and the boot layer it needs (`CRATONVM_COMPAT_FAST_BOOT_BOOT_LAYER`).
        let edits = [
            ("CRATONVM_COMPAT_FAST_BOOT_JDK_BOOTED", Some("1")),
            ("CRATONVM_COMPAT_FAST_BOOT_BOOT_LAYER", Some("1")),
        ];
        cratonvm_types::flags::with_thread_overrides(&edits, || {
            for (m, d) in [("initLevel", "()I"), ("isBooted", "()Z")] {
                assert!(triple_is_retired_shadow(VM, m, d), "{m}{d}");
                assert_eq!(compat_row_of_shadow(VM, m, d), Some(Row::JdkVmInitLevel), "{m}{d}");
            }
        });
        // The other retired `VM` rows: not pure reads of a static `--compatible`
        // writes (see `is_vm_init_level_row`).
        for (m, d) in [
            ("isJavaLangInvokeInited", "()Z"),
            ("setJavaLangInvokeInited", "()V"),
            ("saveProperties", "(Ljava/util/Map;)V"),
            ("getSavedProperty", "(Ljava/lang/String;)Ljava/lang/String;"),
            ("maxDirectMemory", "()J"),
            ("awaitInitLevel", "(I)V"),
            ("initLevel", "(I)V"),
        ] {
            assert_ne!(compat_row_of_shadow(VM, m, d), Some(Row::JdkVmInitLevel), "{m}{d}");
        }
        assert_eq!(compat_family_of_class(VM).map(|f| f.row), None);
        assert_eq!(compat_row_of_stub_class(VM), None);
    }

    #[test]
    fn is_booted_stays_native_when_the_fast_boot_never_raises_the_level() {
        let edits = [("CRATONVM_COMPAT_FAST_BOOT_JDK_BOOTED", Some("0"))];
        cratonvm_types::flags::with_thread_overrides(&edits, || {
            assert_eq!(compat_row_of_shadow(VM, "isBooted", "()Z"), None);
            assert_eq!(
                compat_row_of_shadow(VM, "initLevel", "()I"),
                Some(Row::JdkVmInitLevel)
            );
        });
        // j27 wave 6 (lane T1LAM2): the level write without its boot layer is
        // withheld by the boot, so the stand-in must stay too.
        let edits = [
            ("CRATONVM_COMPAT_FAST_BOOT_JDK_BOOTED", Some("1")),
            ("CRATONVM_COMPAT_FAST_BOOT_BOOT_LAYER", Some("0")),
        ];
        cratonvm_types::flags::with_thread_overrides(&edits, || {
            assert_eq!(compat_row_of_shadow(VM, "isBooted", "()Z"), None);
        });
        assert!(fast_boot_writes_booted_level(true, true));
        assert!(!fast_boot_writes_booted_level(true, false));
        assert!(!fast_boot_writes_booted_level(false, true));
    }

    fn registered(mode: CompatibilityMode, real_jdk: bool, rows: HotSpotAlignments) -> Vec<bool> {
        let mut r = NativeMethodRegistry::new();
        r.set_compatibility_mode(mode);
        r.set_real_jdk(real_jdk);
        r.set_hotspot_alignments(rows);
        r.with_category(NativeKind::SyntheticStub, |r| {
            r.register(VM, "initLevel", "()I", cb);
            r.register(VM, "isBooted", "()Z", cb);
            r.register(VM, "isJavaLangInvokeInited", "()Z", cb);
        });
        [("initLevel", "()I"), ("isBooted", "()Z"), ("isJavaLangInvokeInited", "()Z")]
            .iter()
            .map(|&(m, d)| r.kind_of(VM, m, d).is_some())
            .collect()
    }

    #[test]
    fn compatible_over_a_real_jdk_drops_the_two_registrations_under_the_row() {
        let edits = [
            ("CRATONVM_COMPAT_FAST_BOOT_JDK_BOOTED", Some("1")),
            ("CRATONVM_COMPAT_FAST_BOOT_BOOT_LAYER", Some("1")),
        ];
        cratonvm_types::flags::with_thread_overrides(&edits, the_two_registrations_body);
    }

    fn the_two_registrations_body() {
        let on = HotSpotAlignments::defaults();
        assert!(on.contains(Row::JdkVmInitLevel));
        let off = on.with(Row::JdkVmInitLevel, false);
        let compat = CompatibilityMode::Compatible;
        assert_eq!(registered(compat, true, on), vec![false, false, true]);
        // `-jdk-vm-init-level`: the natives come back (FBTAIL's static-reading
        // `initLevel` callback, the `isBooted` stand-in).
        assert_eq!(registered(compat, true, off), vec![true, true, true]);
        // The synthetic class library keeps them whatever the set says.
        assert_eq!(registered(compat, false, on), vec![true, true, true]);
    }
}
